import{_ as e,b as d,e as a,a8 as r}from"./chunks/framework.CNHV3T2x.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32","entity":"TCustomBitmap32","kind":"Class","declaration":"TCustomBitmap32 = class(TCustomMap)","inheritance":["TObject","TPersistent","TPlainInterfacedPersistent","TNotifiablePersistent","TThreadPersistent","TCustomMap","TCustomBitmap32"],"summary":"Abstract base class for 32-bit ARGB pixel bitmaps in Graphics32, defining backend surface management, sub-pixel sampling, drawing primitives, and resampling.","date":1787830831000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32/TCustomBitmap32/index.md","filePath":"api/GR32/Classes/TCustomBitmap32/index.md","lastUpdated":1787830831000,"timestamp":1787830831000,"datetime":"2026-08-27T11:40:31.000Z","contributors":[]}'),i={name:"api/GR32/TCustomBitmap32/index.md"};function o(n,t,s,c,l,p){return d(),a("div",null,[...t[0]||(t[0]=[r('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p><code>TCustomBitmap32</code> is the primary 2D image data container in Graphics32. It extends <code>TCustomMap</code> with 32-bit ARGB pixel buffer management, hardware-abstracted rendering backends (<code>TCustomBackend</code>), spatial clipping (<code>ClipRect</code>), drawing modes (<code>DrawMode</code>, <code>CombineMode</code>), alpha blending (<code>MasterAlpha</code>), and customizable pixel resamplers (<code>TCustomResampler</code>).</p><p>Pixel elements are represented as 32-bit ARGB colors (<code>TColor32</code>). <code>TCustomBitmap32</code> provides extensive accessor methods for reading and writing pixels at integer, fixed-point (<code>TFixed</code>), or single-precision floating-point (<code>TFloat</code>) sub-pixel coordinates.</p><p>Derived Class: <a href="/api/GR32/TBitmap32/">TBitmap32</a></p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to &quot;Constructors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td>Create</td><td>Initializes a new <code>TCustomBitmap32</code> instance with default or custom backend and dimensions.</td></tr></tbody></table><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="general-lifecycle" tabindex="-1">General &amp; Lifecycle <a class="header-anchor" href="#general-lifecycle" aria-label="Permalink to &quot;General &amp; Lifecycle&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td>Assign</td><td>Copies pixel buffer and properties from another persistent object or bitmap.</td></tr><tr><td>BeginMeasuring</td><td>Begins area change measurement and bounding box calculation.</td></tr><tr><td>BoundsRect</td><td>Returns a <code>TRect</code> representing the bitmap dimensions <code>(0, 0, Width, Height)</code>.</td></tr><tr><td>Changed</td><td>Triggers update notifications for the entire bitmap or a specified sub-rectangle.</td></tr><tr><td>Clear</td><td>Clears the bitmap pixel buffer to zero (<code>clNone32</code>) or a specified <code>TColor32</code> fill color.</td></tr><tr><td>CopyMapTo</td><td>Copies raw map dimensions and pixel data to a target <code>TCustomBitmap32</code>.</td></tr><tr><td>Delete</td><td>Resets bitmap dimensions to zero and releases buffer memory.</td></tr><tr><td>Empty</td><td>Returns <code>True</code> if the bitmap has zero width or height.</td></tr><tr><td>EndMeasuring</td><td>Concludes area change measurement.</td></tr><tr><td>GetPlatformBackendClass</td><td>Class method returning the default platform backend class.</td></tr><tr><td>PropertyChanged</td><td>Notifies the bitmap and backend that a property has changed.</td></tr><tr><td>ReleaseBackend</td><td>Detaches and returns the active backend instance without destroying it.</td></tr><tr><td>ResetClipRect</td><td>Resets <code>ClipRect</code> to cover the full bitmap bounds <code>(0, 0, Width, Height)</code>.</td></tr></tbody></table><h3 id="stream-file-i-o" tabindex="-1">Stream &amp; File I/O <a class="header-anchor" href="#stream-file-i-o" aria-label="Permalink to &quot;Stream &amp; File I/O&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td>LoadFromFile</td><td>Loads bitmap data from a file on disk.</td></tr><tr><td>LoadFromResourceID</td><td>Loads bitmap data from an embedded resource by integer ID.</td></tr><tr><td>LoadFromResourceName</td><td>Loads bitmap data from an embedded resource by string name.</td></tr><tr><td>LoadFromStream</td><td>Loads bitmap data from a stream.</td></tr><tr><td>SaveToFile</td><td>Saves bitmap data to a file on disk in BMP/DIB format.</td></tr><tr><td>SaveToStream</td><td>Saves bitmap data to a stream in BMP/DIB format.</td></tr></tbody></table><h3 id="blitting-alpha-operations" tabindex="-1">Blitting &amp; Alpha Operations <a class="header-anchor" href="#blitting-alpha-operations" aria-label="Permalink to &quot;Blitting &amp; Alpha Operations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td>Draw</td><td>Draws a source bitmap or sub-rectangle onto this bitmap.</td></tr><tr><td>DrawTo</td><td>Draws this bitmap or a sub-rectangle onto a target destination bitmap.</td></tr><tr><td>ResetAlpha</td><td>Resets alpha values of all pixels to <code>$FF</code> (opaque) or a specified alpha component.</td></tr><tr><td>SetPixelT</td><td>Sets a pixel with alpha blending (<code>DrawMode</code> / <code>CombineMode</code>).</td></tr><tr><td>SetPixelTS</td><td>Sets a pixel with alpha blending and boundary clipping.</td></tr></tbody></table><h3 id="lines-drawing-primitives" tabindex="-1">Lines &amp; Drawing Primitives <a class="header-anchor" href="#lines-drawing-primitives" aria-label="Permalink to &quot;Lines &amp; Drawing Primitives&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td>HorzLine</td><td>Draws an unclipped horizontal line at integer coordinates.</td></tr><tr><td>HorzLineS</td><td>Draws a clipped horizontal line at integer coordinates.</td></tr><tr><td>HorzLineT</td><td>Draws an unclipped blended horizontal line at integer coordinates.</td></tr><tr><td>HorzLineTS</td><td>Draws a clipped blended horizontal line at integer coordinates.</td></tr><tr><td>HorzLineTSP</td><td>Draws a clipped blended horizontal line using current stipple pattern.</td></tr><tr><td>HorzLineX</td><td>Draws an unclipped horizontal line at fixed-point coordinates.</td></tr><tr><td>HorzLineXS</td><td>Draws a clipped horizontal line at fixed-point coordinates.</td></tr><tr><td>VertLine</td><td>Draws an unclipped vertical line at integer coordinates.</td></tr><tr><td>VertLineS</td><td>Draws a clipped vertical line at integer coordinates.</td></tr><tr><td>VertLineT</td><td>Draws an unclipped blended vertical line at integer coordinates.</td></tr><tr><td>VertLineTS</td><td>Draws a clipped blended vertical line at integer coordinates.</td></tr><tr><td>VertLineTSP</td><td>Draws a clipped blended vertical line using current stipple pattern.</td></tr><tr><td>VertLineX</td><td>Draws an unclipped vertical line at fixed-point coordinates.</td></tr><tr><td>VertLineXS</td><td>Draws a clipped vertical line at fixed-point coordinates.</td></tr><tr><td>Line</td><td>Draws an unclipped arbitrary line segment at integer coordinates.</td></tr><tr><td>LineS</td><td>Draws a clipped arbitrary line segment at integer coordinates.</td></tr><tr><td>LineT</td><td>Draws an unclipped blended line segment at integer coordinates.</td></tr><tr><td>LineTS</td><td>Draws a clipped blended line segment at integer coordinates.</td></tr><tr><td>LineA</td><td>Draws an unclipped anti-aliased line segment at integer coordinates.</td></tr><tr><td>LineAS</td><td>Draws a clipped anti-aliased line segment at integer coordinates.</td></tr><tr><td>LineX</td><td>Draws an unclipped line segment at fixed-point coordinates.</td></tr><tr><td>LineF</td><td>Draws an unclipped line segment at floating-point coordinates.</td></tr><tr><td>LineXS</td><td>Draws a clipped line segment at fixed-point coordinates.</td></tr><tr><td>LineFS</td><td>Draws a clipped line segment at floating-point coordinates.</td></tr><tr><td>LineXP</td><td>Draws an unclipped line segment using stipple pattern at fixed-point coordinates.</td></tr><tr><td>LineFP</td><td>Draws an unclipped line segment using stipple pattern at floating-point coordinates.</td></tr><tr><td>LineXSP</td><td>Draws a clipped line segment using stipple pattern at fixed-point coordinates.</td></tr><tr><td>LineFSP</td><td>Draws a clipped line segment using stipple pattern at floating-point coordinates.</td></tr><tr><td>MoveTo</td><td>Sets current pen position for subsequent <code>LineTo</code> drawing operations.</td></tr><tr><td>MoveToX</td><td>Sets current fixed-point pen position for subsequent <code>LineTo</code> drawing operations.</td></tr><tr><td>MoveToF</td><td>Sets current floating-point pen position for subsequent <code>LineTo</code> drawing operations.</td></tr><tr><td>LineToS</td><td>Draws a clipped line from current pen position to target integer point.</td></tr><tr><td>LineToTS</td><td>Draws a clipped blended line from current pen position to target integer point.</td></tr><tr><td>LineToAS</td><td>Draws a clipped anti-aliased line from current pen position to target integer point.</td></tr><tr><td>LineToXS</td><td>Draws a clipped line from current fixed-point pen position to target point.</td></tr><tr><td>LineToFS</td><td>Draws a clipped line from current floating-point pen position to target point.</td></tr><tr><td>LineToXSP</td><td>Draws a clipped stippled line from current fixed-point pen position to target point.</td></tr><tr><td>LineToFSP</td><td>Draws a clipped stippled line from current floating-point pen position to target point.</td></tr></tbody></table><h3 id="rectangles-shapes" tabindex="-1">Rectangles &amp; Shapes <a class="header-anchor" href="#rectangles-shapes" aria-label="Permalink to &quot;Rectangles &amp; Shapes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td>FillRect</td><td>Fills an unclipped rectangular region with a specified color.</td></tr><tr><td>FillRectS</td><td>Fills a clipped rectangular region with a specified color.</td></tr><tr><td>FillRectT</td><td>Fills an unclipped rectangular region using alpha blending.</td></tr><tr><td>FillRectTS</td><td>Fills a clipped rectangular region using alpha blending.</td></tr><tr><td>FrameRectS</td><td>Draws a 1-pixel clipped rectangular frame.</td></tr><tr><td>FrameRectTS</td><td>Draws a 1-pixel clipped alpha-blended rectangular frame.</td></tr><tr><td>FrameRectTSP</td><td>Draws a 1-pixel clipped stippled rectangular frame.</td></tr><tr><td>RaiseRectTS</td><td>Draws a 3D bevelled button/panel edge.</td></tr></tbody></table><h3 id="transformations" tabindex="-1">Transformations <a class="header-anchor" href="#transformations" aria-label="Permalink to &quot;Transformations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td>Roll</td><td>Scrolls/shifts pixel contents horizontally and vertically with optional background fill.</td></tr><tr><td>FlipHorz</td><td>Flips pixel contents horizontally (left to right).</td></tr><tr><td>FlipVert</td><td>Flips pixel contents vertically (top to bottom).</td></tr><tr><td>Rotate90</td><td>Rotates bitmap contents 90 degrees clockwise.</td></tr><tr><td>Rotate180</td><td>Rotates bitmap contents 180 degrees.</td></tr><tr><td>Rotate270</td><td>Rotates bitmap contents 270 degrees clockwise (90 degrees counter-clockwise).</td></tr></tbody></table><h3 id="stipple-methods" tabindex="-1">Stipple Methods <a class="header-anchor" href="#stipple-methods" aria-label="Permalink to &quot;Stipple Methods&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td>SetStipple</td><td>Sets custom stipple color array pattern.</td></tr><tr><td>AdvanceStippleCounter</td><td>Advances stipple counter position by specified distance in pixels.</td></tr><tr><td>GetStippleColor</td><td>Evaluates and returns current stipple color.</td></tr></tbody></table><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="pixel-accessors" tabindex="-1">Pixel Accessors <a class="header-anchor" href="#pixel-accessors" aria-label="Permalink to &quot;Pixel Accessors&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Scope</th><th>Description</th></tr></thead><tbody><tr><td>Pixel</td><td><code>TColor32</code></td><td>Public</td><td>Default indexed accessor for reading and writing pixels at integer coordinates <code>[X, Y]</code>.</td></tr><tr><td>PixelS</td><td><code>TColor32</code></td><td>Public</td><td>Boundary-clipped pixel accessor at integer coordinates <code>[X, Y]</code>.</td></tr><tr><td>PixelW</td><td><code>TColor32</code></td><td>Public</td><td>Wrapped pixel accessor at integer coordinates <code>[X, Y]</code>.</td></tr><tr><td>PixelX</td><td><code>TColor32</code></td><td>Public</td><td>Pixel accessor at fixed-point coordinates <code>[X, Y]</code>.</td></tr><tr><td>PixelXS</td><td><code>TColor32</code></td><td>Public</td><td>Boundary-clipped pixel accessor at fixed-point coordinates <code>[X, Y]</code>.</td></tr><tr><td>PixelXW</td><td><code>TColor32</code></td><td>Public</td><td>Wrapped pixel accessor at fixed-point coordinates <code>[X, Y]</code>.</td></tr><tr><td>PixelF</td><td><code>TColor32</code></td><td>Public</td><td>Sub-pixel accessor at floating-point coordinates <code>[X, Y]</code>.</td></tr><tr><td>PixelFS</td><td><code>TColor32</code></td><td>Public</td><td>Boundary-clipped sub-pixel accessor at floating-point coordinates <code>[X, Y]</code>.</td></tr><tr><td>PixelFW</td><td><code>TColor32</code></td><td>Public</td><td>Wrapped sub-pixel accessor at floating-point coordinates <code>[X, Y]</code>.</td></tr><tr><td>PixelFR</td><td><code>TColor32</code></td><td>Public</td><td>Read-only resampled sub-pixel accessor at floating-point coordinates <code>[X, Y]</code>.</td></tr><tr><td>PixelXR</td><td><code>TColor32</code></td><td>Public</td><td>Read-only resampled sub-pixel accessor at fixed-point coordinates <code>[X, Y]</code>.</td></tr></tbody></table><h3 id="pen-stipple-properties" tabindex="-1">Pen &amp; Stipple Properties <a class="header-anchor" href="#pen-stipple-properties" aria-label="Permalink to &quot;Pen &amp; Stipple Properties&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Scope</th><th>Description</th></tr></thead><tbody><tr><td>PenColor</td><td><code>TColor32</code></td><td>Public</td><td>Color used for pen drawing operations (<code>MoveTo</code>, <code>LineTo</code>).</td></tr><tr><td>PenPos</td><td><code>TPoint</code></td><td>Public</td><td>Current integer pen coordinate position.</td></tr><tr><td>PenPosF</td><td><code>TFixedPoint</code></td><td>Public</td><td>Current fixed-point pen coordinate position.</td></tr><tr><td>StippleCounter</td><td><code>Single</code></td><td>Public</td><td>Current phase position index along stipple pattern array.</td></tr><tr><td>StippleStep</td><td><code>Single</code></td><td>Public</td><td>Step distance increment for stipple pattern evaluation.</td></tr></tbody></table><h3 id="buffer-backend-properties" tabindex="-1">Buffer &amp; Backend Properties <a class="header-anchor" href="#buffer-backend-properties" aria-label="Permalink to &quot;Buffer &amp; Backend Properties&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Scope</th><th>Description</th></tr></thead><tbody><tr><td>Backend</td><td><code>TCustomBackend</code></td><td>Public</td><td>Active rendering surface backend instance.</td></tr><tr><td>Bits</td><td><code>PColor32Array</code></td><td>Public</td><td>Pointer to contiguous raw 32-bit ARGB pixel memory buffer.</td></tr><tr><td>ClipRect</td><td><code>TRect</code></td><td>Public</td><td>Clipping rectangle restricting pixel modifications.</td></tr><tr><td>Clipping</td><td><code>Boolean</code></td><td>Public</td><td>Read-only flag indicating if <code>ClipRect</code> active region is smaller than full bitmap dimensions.</td></tr><tr><td>MeasuringMode</td><td><code>Boolean</code></td><td>Public</td><td>Indicates whether area change measurement is active.</td></tr><tr><td>PixelPtr</td><td><code>PColor32</code></td><td>Public</td><td>Pointer to specific pixel at integer coordinates <code>[X, Y]</code>.</td></tr><tr><td>ScanLine</td><td><code>PColor32Array</code></td><td>Public</td><td>Pointer to starting pixel memory location for scanline row <code>[Y]</code>.</td></tr></tbody></table><h3 id="drawing-modes-resampling" tabindex="-1">Drawing Modes &amp; Resampling <a class="header-anchor" href="#drawing-modes-resampling" aria-label="Permalink to &quot;Drawing Modes &amp; Resampling&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Scope</th><th>Description</th></tr></thead><tbody><tr><td>CombineMode</td><td><code>TCombineMode</code></td><td>Published</td><td>Pixel combination mode (<code>cmBlend</code>, <code>cmMerge</code>, <code>cmModulo</code>, etc.).</td></tr><tr><td>DrawMode</td><td><code>TDrawMode</code></td><td>Published</td><td>Draw mode (<code>dmOpaque</code>, <code>dmBlend</code>, <code>dmCustom</code>).</td></tr><tr><td>MasterAlpha</td><td><code>Cardinal</code></td><td>Published</td><td>Global alpha scaling factor (<code>0</code> to <code>255</code>) applied to draw operations.</td></tr><tr><td>OuterColor</td><td><code>TColor32</code></td><td>Published</td><td>Color returned when sampling outside bitmap bounds in safe/transparent mode.</td></tr><tr><td>Resampler</td><td><code>TCustomResampler</code></td><td>Published</td><td>Active resampler engine instance for sub-pixel stretching and sampling.</td></tr><tr><td>ResamplerClassName</td><td><code>string</code></td><td>Published</td><td>Class name string of current resampler engine.</td></tr><tr><td>WrapMode</td><td><code>TWrapMode</code></td><td>Published</td><td>Boundary wrapping mode (<code>wmClamp</code>, <code>wmRepeat</code>, <code>wmMirror</code>).</td></tr></tbody></table><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>OnAreaChanged</td><td><code>TAreaChangedEvent</code></td><td>Fired when a specific sub-rectangle region of pixel memory is updated.</td></tr><tr><td>OnPixelCombine</td><td><code>TPixelCombineEvent</code></td><td>Custom pixel combination callback event when <code>DrawMode = dmCustom</code>.</td></tr></tbody></table>',32)])])}const b=e(i,[["render",o]]);export{m as __pageData,b as default};
